155	export interface TubeGeoOptions {
156	  radial?: number;
157	  step?: number;
158	  vScale?: number;
159	  /** angular range (radians, measured from the bottom) — default full circle */
160	  arc?: number;
161	  /** radius offset (negative = inset toward the axis) */
162	  inset?: number;
163	  /**
164	   * Store the front-face (outward) normal. The faces wind outward, so BackSide/DoubleSide materials
165	   * flip this to the inward normal and light the inside of the tube correctly. The legacy default
166	   * (false) stores -d, which those materials flip to point AWAY from the viewer (dot(N,V) <= 0 →
167	   * full fresnel, un-tinted pale reflections); kept only so the 02 chute / 04 pipe look is unchanged.
168	   */
169	  frontNormals?: boolean;
170	  /** also store the local tube frame per vertex (`tubeAxis`, `tubeUp`) for withTubeStrips('attribute') */
171	  axisAttr?: boolean;
172	  /**
173	   * wave 8: lateral stretch of the cross-section (1 = circle): the `right` component of every wall point is
174	   * multiplied by oval(s) (ref 05 rings are ovals ≈1.75 wider than tall), normals follow the ellipse
175	   */
176	  oval?: (s: number) => number;
177	  /**
178	   * `?env05=1` (Screen 05 only, visual): displacement of the wall point at tunnel coordinate s and angle th (th as
179	   * below: cos th → right, sin th → up), written into `out` as (along the frame's right, along its up), world units.
180	   * Positions only; normals, uv and the strip attributes stay those of the circle. Undefined = unchanged geometry.
181	   */
182	  warp?: TubeWarp;
183	}
184	
185	export function buildTubeGeometry(path: TubePath, s0: number, s1: number, o: TubeGeoOptions = {}): THREE.BufferGeometry {
186	  const radial = o.radial ?? 48;
187	  const step = o.step ?? 0.6;
188	  const vScale = o.vScale ?? 1;
189	  const arc = o.arc ?? Math.PI * 2;
190	  const ns = o.frontNormals ? 1 : -1;
191	  const rings = Math.max(2, Math.ceil((s1 - s0) / step) + 1);
192	  const pos = new Float32Array(rings * (radial + 1) * 3);
193	  const nor = new Float32Array(rings * (radial + 1) * 3);
194	  const uv = new Float32Array(rings * (radial + 1) * 2);
195	  const ax = o.axisAttr ? new Float32Array(rings * (radial + 1) * 3) : null;
196	  const au = o.axisAttr ? new Float32Array(rings * (radial + 1) * 3) : null;
197	  const c = new THREE.Vector3();
198	  const d = new THREE.Vector3();
199	  const wv = new THREE.Vector2();
200	  for (let i = 0; i < rings; i++) {
201	    const s = s0 + ((s1 - s0) * i) / (rings - 1);
202	    const f = path.frame(s);
203	    const r = path.radius(s) + (o.inset ?? 0);
204	    const ov = o.oval ? o.oval(s) : 1;
205	    c.copy(f.pos).addScaledVector(f.up, path.radius(s) - path.depth(s));
206	    for (let j = 0; j <= radial; j++) {
207	      const th = -Math.PI / 2 - arc / 2 + (j / radial) * arc; // centred on the bottom
208	      d.copy(f.right).multiplyScalar(Math.cos(th) * ov).addScaledVector(f.up, Math.sin(th));
209	      const k = i * (radial + 1) + j;
210	      if (ax && au) { f.tan.toArray(ax, k * 3); f.up.toArray(au, k * 3); }
211	      pos[k * 3] = c.x + d.x * r;
212	      pos[k * 3 + 1] = c.y + d.y * r;
213	      pos[k * 3 + 2] = c.z + d.z * r;
214	      if (o.warp) {
215	        o.warp(s, th, wv);
216	        pos[k * 3] += f.right.x * wv.x + f.up.x * wv.y;
217	        pos[k * 3 + 1] += f.right.y * wv.x + f.up.y * wv.y;
218	        pos[k * 3 + 2] += f.right.z * wv.x + f.up.z * wv.y;
219	      }
220	      if (ov !== 1) d.copy(f.right).multiplyScalar(Math.cos(th) / ov).addScaledVector(f.up, Math.sin(th)).normalize();
221	      nor[k * 3] = ns * d.x; nor[k * 3 + 1] = ns * d.y; nor[k * 3 + 2] = ns * d.z;
222	      uv[k * 2] = j / radial;
223	      uv[k * 2 + 1] = s / vScale;
224	    }
225	  }
226	  const idx: number[] = [];
227	  for (let i = 0; i < rings - 1; i++) {
228	    for (let j = 0; j < radial; j++) {
229	      const a = i * (radial + 1) + j, b = a + radial + 1;
230	      idx.push(a, b, a + 1, b, b + 1, a + 1);
231	    }
232	  }
233	  const g = new THREE.BufferGeometry();
234	  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
235	  g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
236	  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
237	  if (ax && au) {
238	    g.setAttribute('tubeAxis', new THREE.BufferAttribute(ax, 3));
239	    g.setAttribute('tubeUp', new THREE.BufferAttribute(au, 3));
240	  }
241	  g.setIndex(idx);
242	  g.computeBoundingSphere();
243	  return g;
244	}
