246	/**
247	 * Washer-tube ring collar (ref 05: "flat gold band with a double contour"): a broad FLAT inner band that
248	 * barely stands off the wall, a dark groove, then a thin raised lip on the near edge (−z, the side the
249	 * rider looks at) whose small camera-facing side catches a bright line. The protrusion is shallow on
250	 * purpose: a deep collar shows a big camera-facing annulus (the old "thick orange pipe" look, 21% gold)
251	 * and pokes through the stream where it hugs the wall (06 arch).
252	 * Lathe around local Z; radial values are fractions of the tube radius, axial values are world units
253	 * (the instance scales z by 1). Interior corners are duplicated so every facet keeps a crisp normal.
254	 */
255	export function collarGeometry(depth = 0.022, lip = 0.012, width = 1.1, segments = 96): THREE.BufferGeometry {
256	  const w = width / 2;
257	  const d = depth;
258	  const lipW = Math.min(0.16, width * 0.15), groove = Math.min(0.07, width * 0.06);
259	  // traversed from +z to -z so LatheGeometry's faces/normals point INWARD (toward the tunnel axis)
260	  const prof: [number, number][] = [
261	    [1.03, w], [1 - d * 0.5, w], // far side (hidden from the rider)
262	    [1 - d, w - 0.05], // far chamfer
263	    [1 - d, -w + lipW + groove + 0.02], // the flat band
264	    [1 - d * 0.55, -w + lipW + groove * 0.5], // dark groove (recessed toward the wall)
265	    [1 - d - lip, -w + lipW], [1 - d - lip, -w + 0.05], // raised lip
266	    [1 - d * 0.35, -w], // lip's camera-facing side → thin bright contour
267	    [1.03, -w],
268	  ];
269	  const pts: THREE.Vector2[] = [];
270	  prof.forEach(([x, y], i) => {
271	    pts.push(new THREE.Vector2(x, y));
272	    if (i > 0 && i < prof.length - 1) pts.push(new THREE.Vector2(x, y)); // crisp facet normals
273	  });
274	  const g = new THREE.LatheGeometry(pts, segments);
275	  g.rotateX(Math.PI / 2); // lathe axis Y → tube axis Z
276	  return g;
277	}
