279	/**
280	 * Ref 05 ring (wave 4): a ROUNDED gold band with a double contour — a thick half-round main band (the
281	 * camera-facing body catches a bright highlight on its crown and falls to copper in its shadowed lower
282	 * half) and, on the camera side (−z), a thin half-round lip separated by a narrow dark groove. Radial
283	 * values are fractions of the ring radius (1 = wall), axial values world units. Lathe around local Z,
284	 * traversed +z → −z so the faces point inward.
285	 */
286	export function roundBandGeometry(height = 0.095, width = 0.78, lipHeight = 0.045, lipWidth = 0.26, groove = 0.07, segments = 96): THREE.BufferGeometry {
287	  const w = (width + groove + lipWidth) / 2;
288	  const yc = w - width / 2, a = width / 2;
289	  const yl = -w + lipWidth / 2, al = lipWidth / 2;
290	  const pts: THREE.Vector2[] = [];
291	  const dup = (x: number, y: number) => { pts.push(new THREE.Vector2(x, y), new THREE.Vector2(x, y)); };
292	  pts.push(new THREE.Vector2(1.03, w));
293	  dup(1.0, w);
294	  for (let i = 1; i < 12; i++) {
295	    const f = (i / 12) * Math.PI;
296	    pts.push(new THREE.Vector2(1 - height * Math.sin(f), yc + a * Math.cos(f)));
297	  }
298	  dup(1.0, yc - a);
299	  pts.push(new THREE.Vector2(1.0 - height * 0.04, yc - a - groove * 0.5));
300	  dup(1.0, yl + al);
301	  for (let i = 1; i < 7; i++) {
302	    const f = (i / 7) * Math.PI;
303	    pts.push(new THREE.Vector2(1 - lipHeight * Math.sin(f), yl + al * Math.cos(f)));
304	  }
305	  dup(1.0, -w);
306	  pts.push(new THREE.Vector2(1.03, -w));
307	  const g = new THREE.LatheGeometry(pts, segments);
308	  g.rotateX(Math.PI / 2); // lathe axis Y → tube axis Z
309	  return g;
310	}
