325	export function buildRings(
326	  path: TubePath,
327	  s0: number,
328	  s1: number,
329	  spacing: number,
330	  material: THREE.Material,
331	  opts: RingOpts = {},
332	): THREE.InstancedMesh {
333	  const list: number[] = [];
334	  for (let s = s0; s <= s1 + 1e-6; s += spacing) list.push(s);
335	  return buildRingsAt(path, list, material, opts, spacing);
