338	/** Same rings at an explicit list of path positions (e.g. one evenly spaced set per tunnel section). */
339	export function buildRingsAt(path: TubePath, list: number[], material: THREE.Material, opts: RingOpts = {}, spacing = 9): THREE.InstancedMesh {
340	  const tube = opts.tube ?? 0.075;
341	  const collar = opts.band ?? opts.collar;
342	  const geo = opts.band ? bandGeometry(opts.band) : opts.collar ? collarGeometry(opts.collar.depth, opts.collar.lip, opts.collar.width, opts.collar.segments) : new THREE.TorusGeometry(1, tube, 14, 72);
343	  const n = Math.max(1, list.length) * (opts.double ? 2 : 1);
344	  const mesh = new THREE.InstancedMesh(geo, material, n);
345	  const m = new THREE.Matrix4();
346	  const q = new THREE.Quaternion();
347	  const basis = new THREE.Matrix4();
348	  const c = new THREE.Vector3();
349	  let k = 0;
350	  for (const s of list) {
351	    for (let dbl = 0; dbl < (opts.double ? 2 : 1); dbl++) {
352	      const ss = s + dbl * spacing * 0.16;
353	      const f = path.frame(ss);
354	      const r = path.radius(ss) - (opts.inset ?? 0.05) + (opts.extra ?? 0);
355	      c.copy(f.pos).addScaledVector(f.up, path.radius(ss) - path.depth(ss));
356	      // (right, up, tan) is left-handed (right = tan × up), so the quaternion below is not the intended
357	      // frame: band rings (05 only) use the right-handed (−right, up, tan) so their lip really sits on the
358	      // camera side (−z); collar/torus rings (04/06/07) keep the legacy orientation unchanged
359	      if (opts.band) basis.makeBasis(f.right.clone().negate(), f.up, f.tan);
360	      else basis.makeBasis(f.right, f.up, f.tan);
361	      q.setFromRotationMatrix(basis);
362	      const sc = dbl ? r * 0.985 : r;
363	      // a collar keeps its axial width in world units; a torus scales uniformly
364	      m.compose(c, q, new THREE.Vector3(sc * (opts.oval ? opts.oval(ss) : 1), sc, collar ? 1 : sc * (dbl ? 0.6 : 1)));
365	      mesh.setMatrixAt(k++, m);
366	    }
367	  }
368	  mesh.count = k;
369	  mesh.instanceMatrix.needsUpdate = true;
370	  mesh.frustumCulled = false;
371	  return mesh;
372	}
